html, body { margin: 0; padding: 0; background: #000; overflow-x: hidden; font-family: sans-serif; }
.blackhole-wrap { position: relative; width: 100%; height: 300vh; }
#bh-canvas { position: fixed; top: 0; left: 0; width: 100%; height: 100vh; z-index: 1; pointer-events: none; }
.bh-text-layer {
  position: fixed; top: 0; left: 0; width: 100%; height: 100vh;
  display: flex; align-items: center; justify-content: center; z-index: 2; pointer-events: none;
}
.bh-msg {
  position: absolute; color: #fff; font-weight: 900; opacity: 0;
  transition: opacity 0.5s; text-shadow: 0 5px 20px rgba(0,0,0,0.9); text-align: center;
}

jsCode:
const mainWrap = document.getElementById('container');
mainWrap.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#000;position:relative;';

mainWrap.innerHTML = `
  <div class="blackhole-wrap">
    <canvas id="bh-canvas"></canvas>
    <div class="bh-text-layer">
      <div id="b1" class="bh-msg" style="font-size:24px; color:#aaa; top:15%;">સ્ક્રોલ કરીને બ્લેક હોલ જુઓ ↓</div>
      <div id="b2" class="bh-msg" style="font-size:40px; color:#ff007f;">GRAVITY PULL</div>
      <div id="b3" class="bh-msg" style="font-size:50px; color:#00ffcc;">SUPERNOVA</div>
    </div>
  </div>
`;

const cvs = document.getElementById('bh-canvas');
const ctx = cvs.getContext('2d');
let W, H;
let particles = [];
const pCount = 1000;
let targetPts = [];

function getTextPoints(txt, size) {
  const tc = document.createElement('canvas');
  tc.width = W; tc.height = H;
  const tctx = tc.getContext('2d');
  tctx.fillStyle = 'white'; tctx.font = `900 ${size}px sans-serif`;
  tctx.textAlign = 'center'; tctx.textBaseline = 'middle';
  tctx.fillText(txt, W/2, H/2);
  const data = tctx.getImageData(0,0,W,H).data;
  let pts = [];
  for(let y=0; y<H; y+=6){
    for(let x=0; x<W; x+=6){
      if(data[(y*W+x)*4+3] > 128) pts.push({x:x, y:y});
    }
  }
  return pts.length ? pts : [{x: W/2, y: H/2}];
}

function initBH() {
  W = cvs.width = window.innerWidth;
  H = cvs.height = window.innerHeight;
  targetPts = getTextPoints('SUPERNOVA', Math.min(W/5, 45));
  particles = [];
  for(let i=0; i<pCount; i++){
    particles.push({
      angle: Math.random() * Math.PI * 2,
      radius: Math.random() * Math.max(W, H),
      speed: Math.random() * 0.02 + 0.005,
      c: `hsl(${280 + Math.random()*60}, 100%, 60%)`,
      x: W/2, y: H/2
    });
  }
}
initBH(); window.addEventListener('resize', initBH);

let prog = 0;
mainWrap.addEventListener('scroll', () => {
  prog = mainWrap.scrollTop / (mainWrap.scrollHeight - mainWrap.clientHeight);
  document.getElementById('b1').style.opacity = (prog < 0.2) ? 1 : 0;
  document.getElementById('b2').style.opacity = (prog > 0.3 && prog < 0.6) ? 1 : 0;
  document.getElementById('b3').style.opacity = (prog > 0.8) ? 1 : 0;
});

function drawBH() {
  ctx.fillStyle = 'rgba(0, 0, 0, 0.2)'; 
  ctx.fillRect(0,0,W,H);

  for(let i=0; i<pCount; i++){
    let p = particles[i];
    let tx, ty;

    if (prog < 0.5) {
      // બ્લેક હોલ ઇફેક્ટ: સ્ક્રોલ કરતા કણો સેન્ટર તરફ ખેંચાય છે
      let pull = 1 - (prog * 2); // 1 થી 0 થશે
      let currentRadius = p.radius * Math.max(pull, 0.05);
      p.angle += p.speed;
      tx = W/2 + Math.cos(p.angle) * currentRadius;
      ty = H/2 + Math.sin(p.angle) * currentRadius;
    } else {
      // સુપરનોવા વિસ્ફોટ: કણો લખાણમાં ગોઠવાઈ જશે
      let morphProg = (prog - 0.5) * 2; 
      let tPt = targetPts[i % targetPts.length];

      // ગોળ ફરતા ફરતા લખાણમાં મોર્ફ થવું
      let explodeRadius = p.radius * 2 * (1 - morphProg);
      let tempX = W/2 + Math.cos(p.angle) * explodeRadius;
      let tempY = H/2 + Math.sin(p.angle) * explodeRadius;

      tx = tempX + (tPt.x - tempX) * morphProg;
      ty = tempY + (tPt.y - tempY) * morphProg;
    }

    p.x += (tx - p.x) * 0.1; p.y += (ty - p.y) * 0.1;
    ctx.beginPath(); ctx.arc(p.x, p.y, 1.5, 0, Math.PI*2);
    ctx.fillStyle = p.c; ctx.fill();
  }
  requestAnimationFrame(drawBH);
}
drawBH();
